// Dicionário original
var DictFaseTQ = ee.Dictionary({
  'CCDRU': 1,
  'DECRETO': 2,
  'NAO_INFORMADO': 3,
  'PORTARIA': 4,
  'RTID': 5,
  'TITULADO': 6,
  'TITULO_ANULADO': 7,
  'TITULO_PARCIAL': 8
});

// Função para criar uma imagem baseada nas entradas do dicionário
function createImageFromDictionary(dictionary) {
  // Inicializar uma imagem vazia
  var emptyImage = ee.Image();

  // Mapeamento das chaves para imagens constantes
  var constantImages = dictionary.map(function (pair) {
    const [key, value] = pair;
    return ee.Image.constant(value).int().rename([key]);
  });

  // Adicionar estas imagens juntas numa única imagem final
  var resultingImage = constantImages.reduce(ee.Function.combineImagesToBanded, emptyImage);

  return resultingImage;
}

// Gerar a imagem resultante
