// Exibição opcional da primeira camada da imagem gerada
Map.addLayer(phaseBasedImage.byte().clip(ee.Geometry.Polygon([[-107.0, 35.0, -116.0, 35.0, -117.0, 38.0, -120.0, 38.0]])), {'min': 0, 'max': 8, 'visRanges': [[0, 9]]}, 'Phase Based Image');
```
